def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    total_opp_c = 0
    total_me_c = 0
    for i in range(n):
        if opp[i] == 'C':
            total_opp_c += 1
        if me[i] == 'C':
            total_me_c += 1

    opp_rate = total_opp_c / n
    my_rate = total_me_c / n

    recent_len = 8 if n >= 8 else n
    recent = opp[n - recent_len:]
    recent_c = 0
    for a in recent:
        if a == 'C':
            recent_c += 1
    recent_rate = recent_c / recent_len

    if recent_len >= 4:
        last4 = opp[-4:]
        last4_c = 0
        for a in last4:
            if a == 'C':
                last4_c += 1
    else:
        last4_c = recent_c
        last4 = recent

    run_def = 0
    for a in reversed(opp):
        if a == 'D':
            run_def += 1
        else:
            break

    defections_total = n - total_opp_c
    if defections_total == 0:
        return 'C'

    if n >= 6 and run_def >= 6:
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    if opp_rate >= 0.92:
        if n > 85:
            return 'C'
        if n % 19 == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if opp_rate <= 0.12 and n >= 8:
        if n % 13 == 0 and rng.random() < 0.07:
            return 'C'
        return 'D'

    if recent_rate >= 0.875 and run_def <= 1:
        if n >= 3 and opp[n - 3:] == ['C', 'C', 'D'] and last_me == 'C':
            if rng.random() < 0.55:
                return 'D'
        return 'C'

    if run_def >= 4:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if run_def == 1:
            if recent_rate >= 0.66:
                if rng.random() < 0.82:
                    return 'C'
                return 'D'
            if n >= 3 and opp[-3] == 'C' and me[-2] == 'C':
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if run_def == 2:
            if recent_rate >= 0.6 and rng.random() < 0.55:
                return 'C'
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if run_def == 3:
            if recent_rate >= 0.55 and rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        if n >= 4:
            last4_me = me[-4:]
            my_recent_d = 0
            for a in last4_me:
                if a == 'D':
                    my_recent_d += 1
            if my_recent_d >= 2:
                return 'C'
        if n > 90:
            if opp_rate > 0.5 and rng.random() < 0.18:
                return 'D'
            return 'C'
        if n % 23 == 0 and rng.random() < 0.06:
            return 'D'
        return 'C'

    return 'C'
